def _d(value):
    return None if value is None else parse_date(value)


def _ds(value):
    return None if value is None else format_date(value)


def _money_json(m):
    return None if m is None else {"minor": m.minor, "currency": m.currency}


def template_to_json(tx):
    data = {
        "date": format_date(tx.date) if is_date(tx.date) else None,
        "payee": tx.payee,
        "narration": tx.narration,
        "flag": tx.flag,
        "tags": list(tx.tags),
        "tags_list": isinstance(tx.tags, list),
        "id": tx.id,
        "postings": [{"account": p.account, "amount": _money_json(p.amount), "note": p.note}
                     for p in tx.postings],
    }
    return json.dumps(data, sort_keys=True, ensure_ascii=False)


def template_from_json(text):
    data = json.loads(text)
    postings = []
    for p in data.get("postings", []):
        amt = p.get("amount")
        postings.append(Posting(p["account"], None if amt is None else Money(amt["minor"], amt["currency"]),
                                p.get("note", "")))
    tags = data.get("tags", [])
    tags = list(tags) if data.get("tags_list") else tuple(tags)
    return Transaction(_d(data.get("date")), data.get("payee", ""), data.get("narration", ""), postings,
                       tags, data.get("flag", "*"), data.get("id"))


def import_base_key(tx):
    p = tx.postings[0]
    return "%s|%s|%s|%d %s" % (format_date(tx.date), tx.payee, p.account, p.amount.minor, p.amount.currency)


# -- the store ----------------------------------------------------------------

class Store:
    """A tallybook book stored in one SQLite file."""

    def __init__(self, conn, path):
        self._conn = conn
        self._path = path

    # opening / closing
    @classmethod
    def open(cls, path, create=False):
        given = os.fspath(path)
        fs = given if isinstance(given, str) else os.fsdecode(given)
        if os.path.isdir(fs):
            raise ConflictError("%s is a directory, not a tallybook database" % fs)
        exists = os.path.exists(fs)
        if not exists:
            if not create:
                raise NotFoundError("no such database: %s" % fs)
            parent = os.path.dirname(os.path.abspath(fs))
            if not os.path.isdir(parent):
                raise NotFoundError("no such directory: %s" % (os.path.dirname(fs) or parent))
        else:
            try:
                with open(fs, "rb") as f:
                    head = f.read(16)
            except OSError as e:
                raise ConflictError("cannot read %s: %s" % (fs, e.strerror or e)) from None
            if head and head != _SQLITE_HEADER:
                raise ConflictError("%s is not a tallybook database" % fs)
        try:
            conn = sqlite3.connect(fs, timeout=5.0, isolation_level=None, check_same_thread=False)
        except sqlite3.Error as e:
            raise ConflictError("cannot open %s: %s" % (fs, e)) from None
        try:
            conn.execute("PRAGMA foreign_keys = ON")
            version = conn.execute("PRAGMA user_version").fetchone()[0]
            if version == 0:
                tables = conn.execute("SELECT COUNT(*) FROM sqlite_master").fetchone()[0]
                if tables:
                    raise ConflictError("%s is not a tallybook database" % fs)
            elif version > LATEST_VERSION:
                raise ConflictError("database is at version %d, newer than this tallybook supports (%d)"
                                    % (version, LATEST_VERSION))
        except sqlite3.Error as e:
            conn.close()
            raise ConflictError("%s is not a tallybook database (%s)" % (fs, e)) from None
        except BaseException:
            conn.close()
            raise
        store = cls(conn, given)
        if version == 0 and create:
            try:
                store.migrate()
            except BaseException:
                store.close()
                raise
        return store

    def close(self):
        if self._conn is not None:
            self._conn.close()
            self._conn = None

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()
        return False

    def _c(self):
        if self._conn is None:
            raise ConflictError("the store is closed")
        return self._conn

    @property
    def path(self):
        return self._path

    @property
    def version(self):
        try:
            return self._c().execute("PRAGMA user_version").fetchone()[0]
        except sqlite3.Error as e:
            raise ConflictError("database error: %s" % e) from None

    def _ready(self):
        v = self.version
        if v != LATEST_VERSION:
            raise ConflictError("database is at version %d, run `tallybook db migrate`" % v)
        return self._conn

    @contextlib.contextmanager
    def _write(self):
        conn = self._ready()
        try:
            conn.execute("BEGIN IMMEDIATE")
        except sqlite3.OperationalError as e:
            raise ConflictError("database is busy: %s" % e) from None
        try:
            yield conn
        except BaseException as e:
            try:
                conn.execute("ROLLBACK")
            except sqlite3.Error:
                pass
            if isinstance(e, sqlite3.Error):
                raise ConflictError("database error: %s" % e) from None
            raise
        else:
            try:
                conn.execute("COMMIT")
            except sqlite3.Error as e:
                try:
                    conn.execute("ROLLBACK")
                except sqlite3.Error:
                    pass
                raise ConflictError("database error: %s" % e) from None

    def _read(self, sql, args=()):
        conn = self._ready()
        try:
            return conn.execute(sql, args).fetchall()
        except sqlite3.OperationalError as e:
            raise ConflictError("database error: %s" % e) from None

    def migrate(self):
        conn = self._c()
        applied = []
        current = self.version
        if current > LATEST_VERSION:
            raise ConflictError("database is at version %d, newer than this tallybook supports" % current)
        for target in range(current + 1, LATEST_VERSION + 1):
            try:
                conn.execute("BEGIN IMMEDIATE")
            except sqlite3.OperationalError as e:
                raise ConflictError("migration to version %d failed: %s" % (target, e)) from None
            try:
                _STEPS[target](conn)
                conn.execute("PRAGMA user_version = %d" % target)
                conn.execute("COMMIT")
            except (sqlite3.Error, _StepFailed) as e:
                try:
                    conn.execute("ROLLBACK")
                except sqlite3.Error:
                    pass
                raise ConflictError("migration to version %d failed: %s" % (target, e)) from None
            applied.append(target)
        return applied

    # -- accounts -----------------------------------------------------------
    def _account_rows(self):
        rows = self._read("SELECT path, type, currency, opened, closed, note FROM accounts")
        out = [Account(r[0], r[1], r[2], _d(r[3]), _d(r[4]), r[5] if r[5] is not None else "")
               for r in rows]
        out.sort(key=lambda a: path_key(a.path))
        return out

    def chart(self):
        chart = Chart()
        for a in self._account_rows():
            try:
                chart.add(a.path, currency=a.currency, opened=a.opened, note=a.note)
            except ChartError:
                try:
                    chart.add(a.path)
                except ChartError:
                    continue
            if a.closed is not None:
                try:
                    chart.close(a.path, a.closed)
                except ChartError:
                    chart.get(a.path).closed = a.closed
        return chart

    def add_account(self, path, type=None, currency=None, opened=None, note=""):
        with self._write() as conn:
            chart = self.chart()
            acc = chart.add(path, type=type, currency=currency, opened=opened, note=note)
            conn.execute("INSERT INTO accounts (path, type, currency, opened, note, closed) "
                         "VALUES (?, ?, ?, ?, ?, NULL)",
                         (acc.path, acc.type, acc.currency, _ds(acc.opened), acc.note))
        return Account(acc.path, acc.type, acc.currency, acc.opened, None, acc.note)

    def get_account(self, path):
        rows = self._read("SELECT path, type, currency, opened, closed, note FROM accounts WHERE path = ?",
                          (path if isinstance(path, str) else "",))
        if not rows or not isinstance(path, str):
            raise NotFoundError("no such account: %s" % (path,))
        r = rows[0]
        return Account(r[0], r[1], r[2], _d(r[3]), _d(r[4]), r[5] if r[5] is not None else "")

    def accounts(self, type=None, under=None, currency=None, include_closed=True):
        if type is not None and type not in TYPES:
            raise ValidationError("invalid account type %r: expected one of %s" % (type, ", ".join(TYPES)))
        out = []
        for a in self._account_rows():
            if type is not None and a.type != type:
                continue
            if under is not None and not (a.path == under or a.path.startswith(str(under) + ":")):
                continue
            if currency is not None and a.currency != currency:
                continue
            if not include_closed and a.closed is not None:
                continue
            out.append(a)
        return out

    def count_accounts(self, type=None, under=None, currency=None, include_closed=True):
        return len(self.accounts(type, under, currency, include_closed))

    def close_account(self, path, on):
        with self._write() as conn:
            self.get_account(path)
            chart = self.chart()
            chart.close(path, on)
            later = conn.execute("SELECT COUNT(*) FROM postings p JOIN transactions t ON t.id = p.tx_id "
                                 "WHERE p.account = ? AND t.date > ?", (path, format_date(on))).fetchone()[0]
            if later:
                raise ConflictError("account %s has postings after %s" % (path, format_date(on)))
            conn.execute("UPDATE accounts SET closed = ? WHERE path = ?", (format_date(on), path))
        return self.get_account(path)

    def set_account_note(self, path, note):
        if not isinstance(note, str):
            raise ValidationError("note must be text")
        with self._write() as conn:
            self.get_account(path)
            conn.execute("UPDATE accounts SET note = ? WHERE path = ?", (note, path))
        return self.get_account(path)

    def delete_account(self, path):
        with self._write() as conn:
            acc = self.get_account(path)
            used = conn.execute("SELECT COUNT(*) FROM postings WHERE account = ?", (path,)).fetchone()[0]

            used = conn.execute("SELECT COUNT(*) FROM postings WHERE account = ?", (path,)).fetchone()[0]
            if used:
                raise ConflictError("account %s has postings and cannot be deleted" % path)
            conn.execute("DELETE FROM accounts WHERE path = ?", (path,))
        return acc

    # -- transactions -------------------------------------------------------
    def _load_transactions(self, ids=None):
        if ids is None:
            txrows = self._read("SELECT id, date, payee, narration, flag FROM transactions")
            prow = self._read("SELECT tx_id, account, minor, currency, note FROM postings ORDER BY tx_id, seq")
            trow = self._read("SELECT tx_id, tag FROM tags")
        else:
            ids = list(ids)
            marks = ",".join("?" * len(ids))
            txrows = self._read("SELECT id, date, payee, narration, flag FROM transactions WHERE id IN (%s)"
                                % marks, ids)
            prow = self._read("SELECT tx_id, account, minor, currency, note FROM postings WHERE tx_id IN (%s) "
                              "ORDER BY tx_id, seq" % marks, ids)
            trow = self._read("SELECT tx_id, tag FROM tags WHERE tx_id IN (%s)" % marks, ids)
        posts = {}
        for tx_id, account, minor, cur, note in prow:
            posts.setdefault(tx_id, []).append(Posting(account, Money(minor, cur), note or ""))
        tags = {}
        for tx_id, tag in trow:
            tags.setdefault(tx_id, set()).add(tag)
        out = []
        for tid, d, payee, narration, flag in txrows:
            out.append(Transaction(parse_date(d), payee, narration or "", posts.get(tid, []),
                                   tuple(sorted(tags.get(tid, ()))), flag, tid))
        out.sort(key=lambda t: (t.date, t.id))
        return out

    def _validator(self):
        return Ledger(self.chart(), self.rate_table())

    def _insert(self, conn, ledger, tx, explicit_ids=False):
        """Validate tx against ledger's chart and store it; returns the stored transaction."""
        if not isinstance(tx, Transaction):
            from tallybook.ledger import LedgerError
            raise LedgerError("not a Transaction: %r" % (tx,))
        clean = Transaction(tx.date, tx.payee, tx.narration, tx.postings, tx.tags, tx.flag, None)
        checked = ledger._check(clean)
        cur = conn.execute("INSERT INTO transactions (date, payee, narration, cleared, flag) VALUES (?, ?, ?, ?, ?)",
                           (format_date(checked.date), checked.payee, checked.narration,
                            1 if checked.flag == "*" else 0, checked.flag))
        tid = cur.lastrowid
        stored_paths = {r[0] for r in conn.execute("SELECT path FROM accounts").fetchall()}
        for seq, p in enumerate(checked.postings):
            if p.account not in stored_paths:
                acc = ledger.chart.get(p.account)
                conn.execute("INSERT INTO accounts (path, type, currency, opened, note, closed) "
                             "VALUES (?, ?, ?, ?, ?, ?)",
                             (acc.path, acc.type, acc.currency, _ds(acc.opened), acc.note, _ds(acc.closed)))
                stored_paths.add(p.account)
            conn.execute("INSERT INTO postings (tx_id, seq, account, minor, currency, note) VALUES (?, ?, ?, ?, ?, ?)",
                         (tid, seq, p.account, p.amount.minor, p.amount.currency, p.note))
        for tag in checked.tags:
            conn.execute("INSERT INTO tags (tx_id, tag) VALUES (?, ?)", (tid, tag))
        return Transaction(checked.date, checked.payee, checked.narration, checked.postings, checked.tags,
                           checked.flag, tid)

    def add_transaction(self, tx):
        with self._write() as conn:
            return self._insert(conn, self._validator(), tx)

    def add_transactions(self, txs, keys=None):
        txs = list(txs)
        if keys is not None:
            if isinstance(keys, str):
                raise ValidationError("keys must be a list of texts")
            keys = list(keys)
            if len(keys) != len(txs) or not all(isinstance(k, str) for k in keys):
                raise ValidationError("keys must be one text per transaction")
        result = BulkAdd()
        with self._write() as conn:
            ledger = self._validator()
            seen = set()
            for i, tx in enumerate(txs):
                key = keys[i] if keys is not None else None
                if key is not None:
                    if key in seen or conn.execute("SELECT 1 FROM import_keys WHERE key = ?",
                                                   (key,)).fetchone():
                        result.skipped.append(i)
                        continue
                try:
                    stored = self._insert(conn, ledger, tx)
                except TallybookError as e:
                    e.detail = dict(e.detail or {}, index=i)
                    raise
                if key is not None:
                    conn.execute("INSERT INTO import_keys (key, tx_id) VALUES (?, ?)", (key, stored.id))
                    seen.add(key)
                result.added.append(stored)
        return result

    def _query(self, query):
        if query is None:
            return None
        from tallybook.query import Query, parse_query
        if isinstance(query, Query):
            return None if query.is_empty else query
        if isinstance(query, str):
            if not query.strip():
                return None
            return parse_query(query, chart=self.chart())
        raise ValidationError("query must be text or a Query")

    def _filtered(self, query):
        q = self._query(query)
        txs = self._load_transactions()
        if q is not None:
            txs = [t for t in txs if q.matches(t)]
        return txs

    def transactions(self, query=None, limit=None, offset=0):
        if limit is not None and (not is_int(limit) or limit < 0):
            raise ValidationError("limit must be a whole number of at least 0")
        if not is_int(offset) or offset < 0:
            raise ValidationError("offset must be a whole number of at least 0")
        txs = self._filtered(query)[offset:]
        if limit is not None:
            txs = txs[:limit]
        return txs

    def count_transactions(self, query=None):
        return len(self._filtered(query))

    def has_import_key(self, key):
        return bool(self._read("SELECT 1 FROM import_keys WHERE key = ?", (key,)))

    def get_transaction(self, id):
        self._ready()
        if not is_int(id):
            raise NotFoundError("no transaction %r" % (id,))
        txs = self._load_transactions([id])
        if not txs:
            raise NotFoundError("no transaction %d" % id)
        return txs[0]

    def delete_transaction(self, id):
        with self._write() as conn:
            tx = self.get_transaction(id)
            conn.execute("DELETE FROM import_keys WHERE tx_id = ?", (id,))
            conn.execute("DELETE FROM tags WHERE tx_id = ?", (id,))
            conn.execute("DELETE FROM postings WHERE tx_id = ?", (id,))
            conn.execute("DELETE FROM transactions WHERE id = ?", (id,))
        return tx

    def ledger(self):
        ledger = Ledger(self.chart(), self.rate_table())
        top = 0
        for tx in self._load_transactions():
            ledger._txs[tx.id] = tx
            top = max(top, tx.id)
        seq = self._read("SELECT seq FROM sqlite_sequence WHERE name = 'transactions'")
        if seq and seq[0][0]:
            top = max(top, seq[0][0])
        ledger._next_id = top + 1
        return ledger

    # -- rates --------------------------------------------------------------
    def set_rate(self, src, dst, rate_text, on):
        RateTable().set(src, dst, rate_text, on)
        with self._write() as conn:
            conn.execute("INSERT OR REPLACE INTO rates (src, dst, on_date, rate_text) VALUES (?, ?, ?, ?)",
                         (src, dst, format_date(on), rate_text))

    def remove_rate(self, src, dst, on):
        with self._write() as conn:
            day = format_date(on) if is_date(on) else str(on)
            cur = conn.execute("DELETE FROM rates WHERE src = ? AND dst = ? AND on_date = ?", (src, dst, day))
            if cur.rowcount == 0:
                raise NotFoundError("no rate %s -> %s set on %s" % (src, dst, day))

    def rate_rows(self):
        rows = self._read("SELECT src, dst, on_date, rate_text FROM rates ORDER BY src, dst, on_date")
        return [(r[0], r[1], parse_date(r[2]), r[3]) for r in rows]

    def rate_table(self):
        table = RateTable()
        for src, dst, d, text in self.rate_rows():
            try:
                table.set(src, dst, text, d)
            except TallybookError:
                continue
        return table

    # -- budgets ------------------------------------------------------------
    def add_budget(self, budget):
        from tallybook.budgets import Budget
        if not isinstance(budget, Budget):
            raise ValidationError("not a Budget: %r" % (budget,))
        with self._write() as conn:
            if conn.execute("SELECT 1 FROM budgets WHERE pattern = ? AND period_kind = ?",
                            (budget.pattern, budget.period_kind)).fetchone():
                raise ConflictError("a budget for %s per %s already exists" % (budget.pattern, budget.period_kind))
            conn.execute("INSERT INTO budgets (pattern, period_kind, minor, currency, start_date) "
                         "VALUES (?, ?, ?, ?, ?)",
                         (budget.pattern, budget.period_kind, budget.amount.minor, budget.amount.currency,
                          format_date(budget.start)))
        return budget

    def _budget_rows(self, where="", args=()):
        from tallybook.budgets import Budget
        rows = self._read("SELECT pattern, period_kind, minor, currency, start_date FROM budgets %s "
                          "ORDER BY pattern, period_kind" % where, args)
        return [Budget(r[0], r[1], Money(r[2], r[3]), parse_date(r[4])) for r in rows]

    def remove_budget(self, pattern, period_kind):
        with self._write() as conn:
            found = self._budget_rows("WHERE pattern = ? AND period_kind = ?", (pattern, period_kind))
            if not found:
                raise NotFoundError("no budget %s per %s" % (pattern, period_kind))
            conn.execute("DELETE FROM budgets WHERE pattern = ? AND period_kind = ?", (pattern, period_kind))
        return found[0]

    def budgets(self):
        out = self._budget_rows()
        out.sort(key=lambda b: (b.pattern, b.period_kind))
        return out

    # -- recurring ----------------------------------------------------------
    def add_recurring(self, rec):
        from tallybook.recurring import Recurring
        if not isinstance(rec, Recurring):
            raise ValidationError("not a Recurring: %r" % (rec,))
        with self._write() as conn:
            if conn.execute("SELECT 1 FROM recurring WHERE name = ?", (rec.name,)).fetchone():
                raise ConflictError("recurring item %s already exists" % rec.name)
            conn.execute("INSERT INTO recurring (name, schedule, template, start_date, end_date, max_count, "
                         "materialized_through) VALUES (?, ?, ?, ?, ?, ?, NULL)",
                         (rec.name, str(rec.schedule), template_to_json(rec.template), format_date(rec.start),
                          _ds(rec.end), rec.count))
        return rec

    def _recurring_rows(self, where="", args=()):
        from tallybook.recurring import Recurring
        rows = self._read("SELECT name, schedule, template, start_date, end_date, max_count, materialized_through "
                          "FROM recurring %s ORDER BY name" % where, args)
        return [(Recurring(r[0], r[1], template_from_json(r[2]), parse_date(r[3]), _d(r[4]), r[5]), _d(r[6]))
                for r in rows]

    def remove_recurring(self, name):
        with self._write() as conn:
            found = self._recurring_rows("WHERE name = ?", (name,))
            if not found:
                raise NotFoundError("no recurring item %s" % (name,))
            conn.execute("DELETE FROM recurring WHERE name = ?", (name,))
        return found[0][0]

    def recurring(self):
        return [r for r, _ in self._recurring_rows()]

    def materialized_through(self, name):
        found = self._recurring_rows("WHERE name = ?", (name,))
        if not found:
            raise NotFoundError("no recurring item %s" % (name,))
        return found[0][1]

    def materialize(self, upto=None, today=None):
        from tallybook.recurring import instantiate, occurrences
        for v in (upto, today):
            if v is not None and not is_date(v):
                raise ValidationError("invalid date %r" % (v,))
        if upto is None and today is None:
            raise ValidationError("materialize needs a horizon: upto or today")
        horizon = min(d for d in (upto, today) if d is not None)
        with self._write() as conn:
            items = self._recurring_rows()
            todo = []
            for rec, through in items:
                begin = rec.start
                if through is not None:
                    begin = max(begin, through + _dt.timedelta(days=1))
                if begin <= horizon:
                    for d in occurrences(rec, begin, horizon):
                        todo.append((d, rec.name, rec))
            todo.sort(key=lambda t: (t[0], t[1]))
            ledger = self._validator()
            out = [self._insert(conn, ledger, instantiate(rec, d)) for d, _, rec in todo]
            for rec, through in items:
                if through is None or horizon > through:
                    conn.execute("UPDATE recurring SET materialized_through = ? WHERE name = ?",
                                 (format_date(horizon), rec.name))
        return out

    # -- rules, settings, profiles -----------------------------------------
    def set_rules(self, text):
        from tallybook.rules import parse_rules
        if not isinstance(text, str):
            raise ValidationError("rules must be text")
        parse_rules(text)
        with self._write() as conn:
            conn.execute("INSERT OR REPLACE INTO rules (id, body) VALUES (1, ?)", (text,))

    def rules_text(self):
        rows = self._read("SELECT body FROM rules WHERE id = 1")
        return rows[0][0] if rows else ""

    def rules(self):
        from tallybook.rules import parse_rules
        return parse_rules(self.rules_text())

    def get_setting(self, key, default=None):
        rows = self._read("SELECT value FROM settings WHERE key = ?", (key if isinstance(key, str) else "",))
        if not rows or not isinstance(key, str):
            return default
        return rows[0][0]

    def set_setting(self, key, value):
        if not isinstance(key, str) or not key:
            raise ValidationError("setting key must be non-empty text")
        if not isinstance(value, str):
            raise ValidationError("setting value must be text")
        with self._write() as conn:
            conn.execute("INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)", (key, value))

    def delete_setting(self, key):
        with self._write() as conn:
            conn.execute("DELETE FROM settings WHERE key = ?", (key if isinstance(key, str) else "",))

    def settings(self):
        return dict(self._read("SELECT key, value FROM settings ORDER BY key"))

    def _check_profile_name(self, name):
        if not isinstance(name, str) or not PROFILE_NAME_RE.fullmatch(name):
            raise ValidationError("invalid profile name %r" % (name,))

    def set_profile(self, name, text):
        from tallybook.csvimport import parse_profile
        self._check_profile_name(name)
        if not isinstance(text, str):
            raise ValidationError("profile must be text")
        parse_profile(text)
        self.set_setting("profile." + name, text)

    def profile_text(self, name):
        if not isinstance(name, str):
            raise NotFoundError("no profile %r" % (name,))
        value = self.get_setting("profile." + name)
        if value is None:
            raise NotFoundError("no profile %s" % name)
        return value

    def profiles(self):
        return sorted(k[len("profile."):] for k in self.settings() if k.startswith("profile."))

    def remove_profile(self, name):
        self.profile_text(name)
        self.delete_setting("profile." + name)

    # -- CSV import ---------------------------------------------------------
    def import_csv(self, text, profile, apply_rules=True):
        from tallybook.csvimport import ImportProfile, import_csv, parse_profile
        self._ready()
        if isinstance(profile, ImportProfile):
            prof = profile
        elif isinstance(profile, str):
            if PROFILE_NAME_RE.fullmatch(profile):
                prof = parse_profile(self.profile_text(profile))
            else:
                prof = parse_profile(profile)
        else:
            raise ValidationError("profile must be a name, profile text or an ImportProfile")
        rules = self.rules() if apply_rules else None
        result = import_csv(text, prof, rules, self._load_transactions())
        if result.errors:
            return ImportOutcome([], list(result.duplicates), list(result.errors))
        dup_counts = {}
        for tx in result.duplicates:
            k = import_base_key(tx)
            dup_counts[k] = dup_counts.get(k, 0) + 1
        keys = []
        for tx in result.transactions:
            k = import_base_key(tx)
            dup_counts[k] = dup_counts.get(k, 0) + 1
            keys.append("%s|%d" % (k, dup_counts[k]))
        bulk = self.add_transactions(result.transactions, keys)
        duplicates = list(result.duplicates) + [result.transactions[i] for i in bulk.skipped]
        return ImportOutcome(bulk.added, duplicates, [])

    # -- journals -----------------------------------------------------------
    def journal(self):
        from tallybook.journal import Journal
        txs = []
        for t in self._load_transactions():
            txs.append(Transaction(t.date, t.payee, t.narration, t.postings, t.tags, t.flag, None))
        return Journal(accounts=self.accounts(), rates=self.rate_rows(), transactions=txs)

    def load_journal(self, journal):
        with self._write() as conn:
            chart = self.chart()
            for a in journal.accounts:
                if chart.is_explicit(a.path) if isinstance(a.path, str) else False:
                    raise ChartError("account %s already exists" % a.path, code="conflict")
                acc = chart.add(a.path, type=a.type, currency=a.currency, opened=a.opened, note=a.note)
                if a.closed is not None:
                    chart.close(a.path, a.closed)
                existing = conn.execute("SELECT 1 FROM accounts WHERE path = ?", (acc.path,)).fetchone()
                if existing:
                    raise ChartError("account %s already exists" % a.path, code="conflict")
                conn.execute("INSERT INTO accounts (path, type, currency, opened, note, closed) "
                             "VALUES (?, ?, ?, ?, ?, ?)",
                             (acc.path, acc.type, acc.currency, _ds(acc.opened), acc.note, _ds(acc.closed)))
            rates = self.rate_table()
            for src, dst, d, text in journal.rates:
                rates.set(src, dst, text, d)
                conn.execute("INSERT OR REPLACE INTO rates (src, dst, on_date, rate_text) VALUES (?, ?, ?, ?)",
                             (src, dst, format_date(d), text))
            ledger = Ledger(chart, rates)
            return [self._insert(conn, ledger, tx) for tx in journal.transactions]

    # -- health -------------------------------------------------------------
    def check(self):
        problems = []
        conn = self._ready()
        try:
            for (msg,) in conn.execute("PRAGMA integrity_check").fetchall():
                if msg != "ok":
                    problems.append("integrity check: %s" % msg)
            q = conn.execute
            for pid, tid in q("SELECT id, tx_id FROM postings WHERE tx_id NOT IN (SELECT id FROM transactions)"):
                problems.append("posting %d points to missing transaction %d" % (pid, tid))
            for tid, tag in q("SELECT tx_id, tag FROM tags WHERE tx_id NOT IN (SELECT id FROM transactions)"):
                problems.append("tag %s points to missing transaction %d" % (tag, tid))
            for key, tid in q("SELECT key, tx_id FROM import_keys "
                              "WHERE tx_id NOT IN (SELECT id FROM transactions)"):
                problems.append("import key %s points to missing transaction %d" % (key, tid))
            for (tid,) in q("SELECT id FROM transactions WHERE id NOT IN (SELECT tx_id FROM postings)"):
                problems.append("transaction %d has no postings" % tid)
            for pid, tid, acc in q("SELECT id, tx_id, account FROM postings "
                                   "WHERE account NOT IN (SELECT path FROM accounts)"):
                problems.append("posting %d of transaction %d is on unknown account %s" % (pid, tid, acc))
            for tid, cur, total in q("SELECT p.tx_id, p.currency, SUM(p.minor) FROM postings p "
                                     "JOIN transactions t ON t.id = p.tx_id "
                                     "GROUP BY p.tx_id, p.currency HAVING SUM(p.minor) != 0"):
                problems.append("transaction %d does not balance in %s (off by %d minor units)"
                                % (tid, cur, total))
        except sqlite3.Error as e:
            problems.append("database error: %s" % e)
        return sorted(problems)

    def backup(self, dest):
        conn = self._ready()
        dest = os.fspath(dest)
        if os.path.exists(dest):
            raise ConflictError("%s already exists" % dest)
        parent = os.path.dirname(os.path.abspath(dest))
        if not os.path.isdir(parent):
            raise NotFoundError("no such directory: %s" % (os.path.dirname(dest) or parent))
        try:
            target = sqlite3.connect(dest)
        except sqlite3.Error as e:
            raise ConflictError("cannot create %s: %s" % (dest, e)) from None
        try:
            conn.backup(target)
        except sqlite3.Error as e:
            target.close()
            try:
                os.remove(dest)
            except OSError:
                pass
            raise ConflictError("backup failed: %s" % e) from None
        target.close()

    def info(self):
        self._ready()
        count = lambda table: self._read("SELECT COUNT(*) FROM %s" % table)[0][0]
        return {
            "path": self._path,
            "version": self.version,
            "accounts": count("accounts"),
            "transactions": count("transactions"),
            "postings": count("postings"),
            "rates": count("rates"),
            "budgets": count("budgets"),
            "recurring": count("recurring"),
        }
"""Plain data records shared by every module."""
from dataclasses import dataclass, field
import datetime as _dt
from typing import List, Optional, Tuple


@dataclass
class Account:
    path: str
    type: str
    currency: Optional[str] = None
    opened: Optional[_dt.date] = None
    closed: Optional[_dt.date] = None
    note: str = ""


@dataclass(frozen=True)
class Posting:
