    if fmt not in ("json", "text"):
        raise ValidationError("unknown format '%s': expected json or text" % fmt)
    return fmt


def _report(req, build):
    from tallybook.reports import render_text
    fmt = _report_format(req)
    args = build[0](req)
    with req.open_store() as store:
        ledger = store.ledger()
    report = build[1](ledger, *args)
    if fmt == "text":
        return text_answer(render_text(report))
