def _reports():
    from tallybook import reports as R

    def tb_params(req):
        return (req.q_date("as_of"),)

    def bs_params(req):
        return (req.q_date("as_of"), req.q_text("convert_to"), req.today_for_report())

    def is_params(req):
        return (req.q_period("period", True), req.q_text("convert_to"))

    def cf_params(req):
        return (req.q_period("period", True),)

    def reg_params(req):
        account = req.q_text("account", True)
        return (account, req.q_period("period"), req.q_bool("rollup", False))

    return {
        "trial-balance": _make_report_route(tb_params, lambda l, a: R.trial_balance(l, a)),
        "balance-sheet": _make_report_route(
            bs_params, lambda l, a, c, t: R.balance_sheet(l, a, convert_to=c, today=t)),
        "income-statement": _make_report_route(
            is_params, lambda l, p, c: R.income_statement(l, p, convert_to=c)),
        "cashflow": _make_report_route(cf_params, lambda l, p: R.cashflow(l, p)),
        "register": _make_report_route(
            reg_params, lambda l, a, p, r: R.register(l, a, period=p, rollup=r)),
    }


def _today_for_report(self):
    return self.today()


Request.today_for_report = _today_for_report

REPORTS = _reports()


IMPORT_TYPES = ("application/json", "text/csv", "text/plain")


def import_csv(req):
    if req.raw_body and req.media_type == "application/json":
        f = req.fields(("csv", "profile", "apply_rules"))
        text = f.text("csv", required=True)
        profile = f.text("profile", required=True)
        apply_rules = f.boolean("apply_rules", True)
    else:
        try:
            text = req.raw_body.decode("utf-8")
        except UnicodeDecodeError:
            from tallybook.errors import ParseError
            raise ParseError("the file is not valid UTF-8") from None
        profile = req.q_text("profile", True)
        apply_rules = req.q_bool("apply_rules", True)
    with req.open_store() as store:
        outcome = store.import_csv(text, profile, apply_rules=apply_rules)
    if outcome.errors:
        raise ValidationError("import failed: " + "; ".join("row %s: %s" % (n, msg) for n, msg in outcome.errors))
    return json_answer({"added": tx_list(outcome.added), "duplicates": tx_list(outcome.duplicates)})


def get_rules(req):
    with req.open_store() as store:
        text = store.rules_text()
    return json_answer({"rules": text})


def put_rules(req):
    f = req.fields(("rules",))
    text = f.text("rules", required=True)
    with req.open_store() as store:
        store.set_rules(text)
        text = store.rules_text()
    return json_answer({"rules": text})


def export(req):
    from tallybook.journal import format_journal
    fmt = req.q_text("format")
    if fmt is None:
        fmt = "json"
    if fmt not in ("json", "csv", "journal"):
        raise ValidationError("unknown format '%s': expected json, csv or journal" % fmt)
    with req.open_store() as store:
        if fmt == "journal":
            return text_answer(format_journal(store.journal()))
        txs = store.transactions()
    if fmt == "csv":
        return text_answer(transactions_to_csv(txs), CSV_TYPE)
    return json_answer(tx_list(txs))


# -- the routing table ----------------------------------------------------
# Each entry: (pattern, {verb: (handler, body kinds or None)}). In a pattern a
# literal piece must match exactly and None binds any piece.

JSON_ONLY = ("application/json",)

ROUTES = [
    (("health",), {"GET": (health, None)}),
    (("accounts",), {"GET": (list_accounts, None), "POST": (add_account, JSON_ONLY)}),
    (("accounts", None), {"GET": (get_account, None)}),
    (("accounts", None, "close"), {"POST": (close_account, JSON_ONLY)}),
    (("transactions",), {"GET": (list_transactions, None), "POST": (add_transaction, JSON_ONLY)}),
    (("transactions", None), {"GET": (get_transaction, None), "DELETE": (delete_transaction, None)}),
    (("rates",), {"GET": (list_rates, None), "PUT": (put_rate, JSON_ONLY), "DELETE": (delete_rate, None)}),
    (("budgets",), {"GET": (list_budgets, None), "POST": (add_budget, JSON_ONLY),
                    "DELETE": (delete_budget, None)}),
    (("budgets", "status"), {"GET": (budget_status, None)}),
    (("recurring",), {"GET": (list_recurring, None), "POST": (add_recurring, JSON_ONLY),
                      "DELETE": (delete_recurring, None)}),
    (("recurring", "materialize"), {"POST": (materialize, JSON_ONLY)}),
    (("import",), {"POST": (import_csv, IMPORT_TYPES)}),
    (("rules",), {"GET": (get_rules, None), "PUT": (put_rules, JSON_ONLY)}),
    (("export",), {"GET": (export, None)}),
] + [(("reports", name), {"GET": (route, None)}) for name, route in REPORTS.items()]


def match(pieces):
    """(verbs, params) for the route matching the decoded path pieces, or None."""
    for pattern, verbs in ROUTES:
        if len(pattern) != len(pieces):
            continue
        params = []
        for want, got in zip(pattern, pieces):
            if want is None:
                params.append(got)
            elif want != got:
                break
        else:
            return verbs, params
    return None

