"""The routes of the web API: request shape checks and calls into the store."""
import datetime as _dt
import re

import tallybook
from tallybook.dates import Period, format_date, parse_date
from tallybook.errors import ValidationError
from tallybook.export import money_to_dict, to_json, transaction_to_dict, transactions_to_csv
from tallybook.model import Posting, Transaction
from tallybook.money import Money

MAX_INT = 9223372036854775807
_DIGITS_RE = re.compile(r"[0-9]+")
_TAG_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")
_YES = ("true", "yes", "1")
_NO = ("false", "no", "0")
JSON_TYPE = "application/json; charset=utf-8"
TEXT_TYPE = "text/plain; charset=utf-8"
CSV_TYPE = "text/csv; charset=utf-8"


class Answer:
    """What a route answers: status, body bytes and content type."""

    def __init__(self, status, body, content_type=JSON_TYPE):
        self.status = status
        self.body = body
        self.content_type = content_type


def json_answer(value, status=200):
    return Answer(status, to_json(value).encode("utf-8"), JSON_TYPE)


def text_answer(text, content_type=TEXT_TYPE):
    return Answer(200, text.encode("utf-8"), content_type)


# -- the request as the routes see it -------------------------------------

class Request:
    def __init__(self, server, params, query, body, media_type, raw_body):
        self.server = server          # has .db_path and .today
        self.params = params          # decoded path pieces bound by the route
        self.query = query            # dict name -> text (last wins)
        self.body = body              # dict (JSON object) or None when not JSON
        self.media_type = media_type  # lower-cased type of the body, or None
        self.raw_body = raw_body      # bytes

    def today(self):
        return self.server.today if self.server.today is not None else _dt.date.today()

    def open_store(self):
        from tallybook.storage import Store
        return Store.open(self.server.db_path)

    # query helpers
    def q_text(self, name, required=False):
        value = self.query.get(name)
        if value is None and required:
            raise ValidationError("missing query parameter: %s" % name)
        return value

    def q_bool(self, name, default):
        value = self.query.get(name)
        if value is None:
            return default
        low = value.lower()
        if low in _YES:
            return True
        if low in _NO:
            return False
        raise ValidationError("invalid value for %s: '%s' (expected true, false, yes, no, 1 or 0)" % (name, value))

    def q_int(self, name, default):
        value = self.query.get(name)
        if value is None:
            return default
        if not _DIGITS_RE.fullmatch(value) or int(value) > MAX_INT:
            raise ValidationError("invalid value for %s: '%s' (expected a whole number from 0 to %d)"
                                  % (name, value, MAX_INT))
        return int(value)

    def q_date(self, name, required=False):
        value = self.q_text(name, required)
        return None if value is None else parse_date(value)

    def q_period(self, name, required=False):
        value = self.q_text(name, required)
        return None if value is None else Period.parse(value)

    def fields(self, allowed):
        return Fields(self.body if self.body is not None else {}, allowed)


class Fields:
    """Checks the fields of one JSON object."""

    def __init__(self, obj, allowed, where=""):
        self.obj = obj
        self.where = where
        unknown = sorted(k for k in obj if k not in allowed)
        if unknown:
            raise ValidationError("unknown field: %s%s" % (unknown[0], where))

    def _value(self, name, required):
        value = self.obj.get(name)
        if value is None and required:
            raise ValidationError("missing field: %s%s" % (name, self.where))
        return value

    def _wrong(self, name, what):
        return ValidationError("field %s%s must be %s" % (name, self.where, what))

    def raw(self, name, required=False):
        return self._value(name, required)

    def text(self, name, required=False, default=None):
        value = self._value(name, required)
        if value is None:
            return default
        if not isinstance(value, str):
            raise self._wrong(name, "text")
        return value

    def boolean(self, name, default):
        value = self._value(name, False)
        if value is None:
            return default
        if not isinstance(value, bool):
            raise self._wrong(name, "true or false")
        return value

    def date(self, name, required=False):
        value = self._value(name, required)
        if value is None:
            return None
        if not isinstance(value, str):
            raise self._wrong(name, "a date text YYYY-MM-DD")
        return parse_date(value)

    def object(self, name, required=False):
        value = self._value(name, required)
        if value is None:
            return None
        if not isinstance(value, dict):
            raise self._wrong(name, "an object")
        return value

    def text_list(self, name):
        value = self._value(name, False)
        if value is None:
            return []
        if not isinstance(value, list) or not all(isinstance(v, str) for v in value):
            raise self._wrong(name, "a list of texts")
        return value

    def money(self, name, required=False):
        value = self._value(name, required)
        if value is None:
            return None
        return read_money(value, "field %s%s" % (name, self.where))


def read_money(value, what):
    if isinstance(value, str):
        return Money.parse(value)
    if isinstance(value, dict):
        if set(value) != {"amount", "currency"}:
            raise ValidationError('%s must be {"amount": ..., "currency": ...} or text like "12.50 USD"' % what)
        amount, currency = value["amount"], value["currency"]
        if not isinstance(amount, str) or not isinstance(currency, str):
            raise ValidationError("%s: amount and currency must be text" % what)
        return Money.of(amount, currency)
    raise ValidationError('%s must be {"amount": ..., "currency": ...} or text like "12.50 USD"' % what)


def read_postings(f, name="postings"):
    value = f.raw(name, required=True)
    if not isinstance(value, list):
        raise ValidationError("field %s must be a list of postings" % name)
    out = []
    for i, item in enumerate(value, 1):
        where = " (posting %d)" % i
        if not isinstance(item, dict):
            raise ValidationError("posting %d must be an object" % i)
        pf = Fields(item, ("account", "amount", "note"), where)
        account = pf.text("account", required=True)
        amount = pf.money("amount")
        note = pf.text("note", default="")
        out.append(Posting(account, amount, note))
    return out


# -- JSON shapes ----------------------------------------------------------

def _date(d):
    return None if d is None else format_date(d)


def account_dict(a):
    return {"path": a.path, "type": a.type, "currency": a.currency, "opened": _date(a.opened),
            "closed": _date(a.closed), "note": a.note}


def rate_dict(src, dst, d, text):
    return {"src": src, "dst": dst, "date": format_date(d), "rate": text}


def budget_dict(b):
    return {"pattern": b.pattern, "period_kind": b.period_kind, "amount": money_to_dict(b.amount),
            "start": format_date(b.start)}


def recurring_dict(r):
    t = r.template
    return {
        "name": r.name, "schedule": str(r.schedule), "start": format_date(r.start), "end": _date(r.end),
        "count": r.count,
        "template": {
            "payee": t.payee, "narration": t.narration, "flag": t.flag, "tags": sorted(set(t.tags)),
            "postings": [{"account": p.account, "amount": money_to_dict(p.amount), "note": p.note}
                         for p in t.postings],
        },
    }


def tx_list(txs):
    return [transaction_to_dict(t) for t in txs]


# -- routes ---------------------------------------------------------------

def health(req):
    with req.open_store() as store:
        version = store.version
    return json_answer({"status": "ok", "version": tallybook.__version__, "schema_version": version})


def list_accounts(req):
    type_ = req.q_text("type")
    under = req.q_text("under")
    currency = req.q_text("currency")
    include_closed = req.q_bool("include_closed", True)
    with req.open_store() as store:
        accs = store.accounts(type=type_, under=under, currency=currency, include_closed=include_closed)
    return json_answer([account_dict(a) for a in accs])


def add_account(req):
    f = req.fields(("path", "type", "currency", "opened", "note"))
    path = f.text("path", required=True)
    type_ = f.text("type")
    currency = f.text("currency")
    opened = f.date("opened")
    note = f.text("note", default="")
    with req.open_store() as store:
        acc = store.add_account(path, type=type_, currency=currency, opened=opened, note=note)
    return json_answer(account_dict(acc), 201)


def get_account(req):
    with req.open_store() as store:
        acc = store.get_account(req.params[0])
    return json_answer(account_dict(acc))


def close_account(req):
    f = req.fields(("on",))
    on = f.date("on")
    if on is None:
        on = req.today()
    with req.open_store() as store:
        acc = store.close_account(req.params[0], on)
    return json_answer(account_dict(acc))


def list_transactions(req):
    q = req.q_text("q")
    limit = req.q_int("limit", None)
    offset = req.q_int("offset", 0)
    with req.open_store() as store:
        txs = store.transactions(q)
    page = txs[offset:]
    if limit is not None:
        page = page[:limit]
    return json_answer({"items": tx_list(page), "total": len(txs), "limit": limit, "offset": offset})


def _build_tx(f, date):
    payee = f.text("payee", required=True)
    postings = read_postings(f)
    narration = f.text("narration", default="")
    flag = f.text("flag", default="*")
    tags = f.text_list("tags")
    return Transaction(date, payee, narration, postings, tuple(tags), flag, None)


def add_transaction(req):
    f = req.fields(("date", "payee", "narration", "flag", "tags", "postings"))
    date = f.date("date", required=True)
    tx = _build_tx(f, date)
    with req.open_store() as store:
        stored = store.add_transaction(tx)
    return json_answer(transaction_to_dict(stored), 201)


def _tx_id(req):
    from tallybook.errors import NotFoundError
    text = req.params[0]
    if not _DIGITS_RE.fullmatch(text) or int(text) > MAX_INT or int(text) < 1:
        raise NotFoundError("no transaction %s" % text)
    return int(text)


def get_transaction(req):
    tid = _tx_id(req)
    with req.open_store() as store:
        tx = store.get_transaction(tid)
    return json_answer(transaction_to_dict(tx))


def delete_transaction(req):
    tid = _tx_id(req)
    with req.open_store() as store:
        tx = store.delete_transaction(tid)
    return json_answer(transaction_to_dict(tx))


def list_rates(req):
    with req.open_store() as store:
        rows = store.rate_rows()
    return json_answer([rate_dict(*r) for r in rows])


def put_rate(req):
    f = req.fields(("src", "dst", "date", "rate"))
    src = f.text("src", required=True)
    dst = f.text("dst", required=True)
    on = f.date("date", required=True)
    rate = f.text("rate", required=True)
    with req.open_store() as store:
        store.set_rate(src, dst, rate, on)
    return json_answer(rate_dict(src, dst, on, rate))


def delete_rate(req):
    src = req.q_text("src", True)
    dst = req.q_text("dst", True)
    on_text = req.q_text("date", True)
    on = parse_date(on_text)
    with req.open_store() as store:
        found = [r for r in store.rate_rows() if r[0] == src and r[1] == dst and r[2] == on]
        store.remove_rate(src, dst, on)
    row = found[0] if found else (src, dst, on, "")
    return json_answer(rate_dict(*row))


def list_budgets(req):
    with req.open_store() as store:
        budgets = store.budgets()
    return json_answer([budget_dict(b) for b in budgets])


def add_budget(req):
    from tallybook.budgets import Budget
    f = req.fields(("pattern", "period_kind", "amount", "start"))
    pattern = f.text("pattern", required=True)
    kind = f.text("period_kind", required=True)
    amount = f.money("amount", required=True)
    start = f.date("start", required=True)
    budget = Budget(pattern, kind, amount, start)
    with req.open_store() as store:
        store.add_budget(budget)
    return json_answer(budget_dict(budget), 201)


def delete_budget(req):
    pattern = req.q_text("pattern", True)
    kind = req.q_text("period_kind", True)
    with req.open_store() as store:
        budget = store.remove_budget(pattern, kind)
    return json_answer(budget_dict(budget))


def budget_status(req):
    from tallybook.budgets import budget_status as status
    period = req.q_period("period", True)
    with req.open_store() as store:
        lines = status(store.budgets(), store.ledger(), period)
    return json_answer([line.to_dict() for line in lines])


def list_recurring(req):
    with req.open_store() as store:
        items = store.recurring()
    return json_answer([recurring_dict(r) for r in items])


def add_recurring(req):
    from tallybook.recurring import Recurring
    f = req.fields(("name", "schedule", "start", "end", "count", "template"))
    name = f.raw("name", required=True)
    schedule = f.raw("schedule", required=True)
    start = f.date("start", required=True)
    end = f.date("end")
    count = f.raw("count")
    tobj = f.object("template", required=True)
    tf = Fields(tobj, ("payee", "narration", "flag", "tags", "postings"), " (template)")
    template = _build_tx(tf, None)
    if template.flag not in ("*", "!"):
        raise ValidationError("invalid flag '%s' (template): expected * or !" % template.flag)
    for tag in template.tags:
        if not _TAG_RE.fullmatch(tag):
            raise ValidationError("invalid tag '%s' (template)" % tag)
    rec = Recurring(name, schedule, template, start, end, count)
    with req.open_store() as store:
        store.add_recurring(rec)
