def delete_recurring(req):
    name = req.q_text("name", True)
    with req.open_store() as store:
        rec = store.remove_recurring(name)
    return json_answer(recurring_dict(rec))


def materialize(req):
    f = req.fields(("upto",))
    upto = f.date("upto")
    today = req.today()
    with req.open_store() as store:
