"""The web API: a small JSON-over-HTTP server on one book file (standard library only)."""
import http.client
import json
import re
import signal
import socket
import socketserver
import sys
import threading
from http import HTTPStatus
from http.server import ThreadingHTTPServer
from urllib.parse import parse_qsl, unquote

from tallybook.api import handlers
from tallybook.errors import ConflictError, ParseError, TallybookError, ValidationError

__all__ = ["serve"]

MAX_BODY = 1048576
_MAX_LINE = 65536
_DRAIN_CAP = 256 * 1048576
_VERSION_RE = re.compile(r"HTTP/[0-9]+\.[0-9]+")
_ABSOLUTE_RE = re.compile(r"[A-Za-z][A-Za-z0-9+.-]*://[^/?#]*(.*)", re.S)
_HEX_RE = re.compile(rb"[0-9A-Fa-f]+")
_STATUS_FOR_CODE = {"parse": 400, "validation": 400, "not_found": 404, "conflict": 409}


class _Reply(Exception):
    """An answer decided before the route runs (404, 405, 413, 415, 400)."""

    def __init__(self, status, message, headers=(), drain=True):
        super().__init__(message)
        self.status = status
        self.message = message
        self.headers = list(headers)
        self.drain = drain


class _ClientGone(Exception):
    pass


def _reason(status):
    try:
        return HTTPStatus(status).phrase
    except ValueError:
        return "Unknown"


def _error_body(message):
    return handlers.to_json({"error": message or "error"}).encode("utf-8")


def _status_of(error):
    return _STATUS_FOR_CODE.get(getattr(error, "code", None), 400)


def _decode_pieces(raw_path):
    """The percent-decoded path pieces, or None when the path cannot be a route."""
    if not raw_path.startswith("/"):
        return None
    pieces = []
    for piece in raw_path[1:].split("/"):
        if piece == "":
            return None
        try:
            pieces.append(unquote(piece, encoding="utf-8", errors="strict"))
        except UnicodeDecodeError:
            return None
    return pieces


def _media_type(value):
    if value is None:
        return None
    kind = value.split(";", 1)[0].strip().lower()
    return kind or None


def _parse_json_body(raw):
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        raise ParseError("the body is not valid UTF-8") from None

    def bad_constant(name):
        raise ValueError("%s is not allowed in JSON" % name)

    try:
        value = json.loads(text, parse_constant=bad_constant)
    except (ValueError, RecursionError) as e:
        raise ParseError("the body is not valid JSON: %s" % e) from None
    if not isinstance(value, dict):
        raise ValidationError("the body must be a JSON object")
    return value


class _Handler(socketserver.StreamRequestHandler):
    timeout = 30

    def setup(self):
        super().setup()
        self._answered = False
        self._method = None
        self._pending = 0          # body bytes the client may still send
        self._expect_continue = False

    # -- low level ----------------------------------------------------------
    def _send(self, status, body, content_type, extra=()):
        lines = ["HTTP/1.1 %d %s" % (status, _reason(status)),
                 "Content-Type: %s" % content_type,
                 "Content-Length: %d" % len(body),
                 "Connection: close"]
        lines.extend("%s: %s" % kv for kv in extra)
        head = ("\r\n".join(lines) + "\r\n\r\n").encode("latin-1")
        self._answered = True
        payload = head if self._method == "HEAD" else head + body
        try:
            self.wfile.write(payload)
            self.wfile.flush()
        except OSError:
            pass

    def _send_error(self, status, message, extra=()):
        self._send(status, _error_body(message), handlers.JSON_TYPE, extra)

    def _drain(self):
        """Read and throw away the rest of a body the client is sending."""
        remaining = min(self._pending, _DRAIN_CAP)
        try:
            while remaining > 0:
                chunk = self.rfile.read(min(remaining, 65536))
                if not chunk:
                    break
                remaining -= len(chunk)
        except OSError:
            pass
        self._pending = 0

    # -- reading the request ------------------------------------------------
    def _read_request_line(self):
        for _ in range(8):
            line = self.rfile.readline(_MAX_LINE + 1)
            if not line:
                return None
            if len(line) > _MAX_LINE or not line.endswith(b"\n"):
                raise _Reply(400, "the request line is too long or incomplete", drain=False)
            if line.strip(b"\r\n"):
                return line
        raise _Reply(400, "no request line", drain=False)

    def _read_chunked(self):
        body = []
        total = 0
        too_large = False
        while True:
            line = self.rfile.readline(_MAX_LINE + 1)
            if not line:
                raise _ClientGone()
            size_text = line.split(b";", 1)[0].strip()
            if not _HEX_RE.fullmatch(size_text):
                raise _Reply(400, "bad chunked body", drain=False)
            size = int(size_text, 16)
            if size == 0:
                while True:
                    trailer = self.rfile.readline(_MAX_LINE + 1)
                    if not trailer or trailer in (b"\r\n", b"\n"):
                        break
                break
            total += size
            if total > _DRAIN_CAP:
                raise _Reply(413, "the body is larger than %d bytes" % MAX_BODY, drain=False)
            data = self.rfile.read(size)
            if len(data) < size:
                raise _ClientGone()
            if total > MAX_BODY:
                too_large = True
            else:
                body.append(data)
            self.rfile.readline(_MAX_LINE + 1)
        if too_large:
            raise _Reply(413, "the body is larger than %d bytes" % MAX_BODY, drain=False)
        return b"".join(body)

    # -- one request --------------------------------------------------------
    def handle(self):
        try:
            self._handle_one()
        except _ClientGone:
            pass
        except Exception:  # never print, always answer
            if not self._answered:
                try:
                    self._send_error(500, "internal server error")
                except Exception:
                    pass

    def _handle_one(self):
        try:
            self._route_request()
        except _Reply as r:
            if r.drain and not self._expect_continue:
                self._drain()
            self._send_error(r.status, r.message, r.headers)

    def _route_request(self):
        raw = self._read_request_line()
        if raw is None:
            return
        words = raw.decode("latin-1").rstrip("\r\n").split()
        if len(words) != 3 or not _VERSION_RE.fullmatch(words[2]):
            raise _Reply(400, "cannot read the request line", drain=False)
        method, target, _version = words
        self._method = method
        try:
            headers = http.client.parse_headers(self.rfile)
        except (http.client.HTTPException, ValueError):
            raise _Reply(400, "cannot read the request headers", drain=False) from None

        # body framing first, so that early answers can still drain the body
        transfer = headers.get("Transfer-Encoding")
        chunked = False
        if transfer is not None and transfer.strip().lower() != "identity":
            codings = [c.strip().lower() for c in transfer.split(",")]
            if codings[-1] != "chunked":
                raise _Reply(400, "unsupported Transfer-Encoding", drain=False)
            chunked = True
        length = 0
        length_error = None
        if not chunked:
            values = headers.get_all("Content-Length") or []
            texts = set(v.strip() for v in values)
            if texts:
                if len(texts) != 1 or not next(iter(texts)).isdigit() or not next(iter(texts)).isascii():
                    length_error = "Content-Length must be a whole number"
                else:
                    length = int(next(iter(texts)))
                    self._pending = length
        self._expect_continue = (headers.get("Expect", "").strip().lower() == "100-continue")

        # the path
        target = target.split("#", 1)[0]
        m = _ABSOLUTE_RE.fullmatch(target)
        if m:
            target = m.group(1) or "/"
        raw_path, _, query_text = target.partition("?")
        pieces = _decode_pieces(raw_path)
        found = handlers.match(pieces) if pieces is not None else None
        if found is None:
            if length_error:
                raise _Reply(400, length_error, drain=False)
            raise _Reply(404, "no such path: %s" % raw_path)
        verbs, params = found

        # the verb
        if method not in verbs:
            if length_error:
                raise _Reply(400, length_error, drain=False)
            allow = ", ".join(sorted(verbs))
            raise _Reply(405, "method %s is not allowed on %s" % (method, raw_path), [("Allow", allow)])
        route, kinds = verbs[method]

        # the body: length, type, then reading it
        if length_error:
            raise _Reply(400, length_error, drain=False)
        if not chunked and length > MAX_BODY:
            raise _Reply(413, "the body is larger than %d bytes" % MAX_BODY)
        media = _media_type(headers.get("Content-Type"))
        takes_body = method in ("POST", "PUT")
        if takes_body and kinds is not None and (chunked or length > 0) and media not in kinds:
            if not chunked:
                raise _Reply(415, "unsupported Content-Type: %s" % (headers.get("Content-Type") or "none"))
        if self._expect_continue and (chunked or length > 0):
            try:
                self.wfile.write(b"HTTP/1.1 100 Continue\r\n\r\n")
                self.wfile.flush()
            except OSError:
                raise _ClientGone() from None
            self._expect_continue = False
        if chunked:
            body = self._read_chunked()
            if takes_body and kinds is not None and body and media not in kinds:
                raise _Reply(415, "unsupported Content-Type: %s" % (headers.get("Content-Type") or "none"),
                             drain=False)
        else:
            body = self.rfile.read(length) if length else b""
            if len(body) < length:
                raise _ClientGone()
            self._pending = 0

        try:
            parsed = None
            if takes_body:
                if media == "application/json" or (kinds == handlers.JSON_ONLY):
                    parsed = _parse_json_body(body) if body else {}
            query = dict(parse_qsl(query_text, keep_blank_values=True))
            request = handlers.Request(self.server, params, query, parsed, media if body else None, body)
            answer = route(request)
        except TallybookError as e:
            self._send_error(_status_of(e), e.message or type(e).__name__)
            return
        except RecursionError:
            self._send_error(400, "the request is nested too deeply")
            return
        self._send(answer.status, answer.body, answer.content_type)

    def finish(self):
        # Close gently: stop sending, then read what the client still sends,
        # so that closing the socket does not reset the connection.
        try:
            self.wfile.flush()
        except OSError:
            pass
        try:
            self.connection.shutdown(socket.SHUT_WR)
            self.connection.settimeout(2)
            got = 0
            while got < _DRAIN_CAP:
                data = self.connection.recv(65536)
                if not data:
                    break
                got += len(data)
        except OSError:
            pass
        try:
            super().finish()
        except OSError:
            pass


class _Server(ThreadingHTTPServer):
    daemon_threads = True
    block_on_close = False
    allow_reuse_address = True

    def server_bind(self):
        # skip HTTPServer's reverse DNS lookup of the host
        socketserver.TCPServer.server_bind(self)
        host, port = self.server_address[:2]
        self.server_name = host
        self.server_port = port

    def handle_error(self, request, client_address):
        pass


class _Server6(_Server):
    address_family = socket.AF_INET6


def serve(db_path, host="127.0.0.1", port=0, today=None, *, _stop=None):
    """Serve the book at db_path until SIGINT or SIGTERM; returns 0."""
    from tallybook.storage import LATEST_VERSION, Store

    with Store.open(db_path) as store:
        version = store.version
        if version != LATEST_VERSION:
            raise ConflictError("database is at version %d, run `tallybook db migrate`" % version)

    cls = _Server6 if ":" in str(host) else _Server
    server = cls((host, port), _Handler)
    server.db_path = db_path
    server.today = today

    stop = _stop if _stop is not None else threading.Event()
    previous = {}
    if threading.current_thread() is threading.main_thread():
        def on_signal(signum, frame):
            stop.set()

        for sig in (signal.SIGINT, signal.SIGTERM):
            try:
                previous[sig] = signal.signal(sig, on_signal)
            except (ValueError, OSError):
                pass

    worker = threading.Thread(target=server.serve_forever, kwargs={"poll_interval": 0.2},
                              name="tallybook-api", daemon=True)
    try:
        worker.start()
        real_port = server.server_address[1]
        shown = "[%s]" % host if ":" in str(host) else host
        sys.stdout.write("tallybook listening on http://%s:%d\n" % (shown, real_port))
        sys.stdout.flush()
        while not stop.wait(0.5):
            pass
    finally:
        server.shutdown() if worker.is_alive() else None
        worker.join(5)
        server.server_close()
        for sig, handler in previous.items():
            try:
                signal.signal(sig, handler)
            except (ValueError, OSError, TypeError):
                pass
    return 0

